insert into public.communities (id, name, tamil_name, description, tamil_description, visible_members, active) values
  ('iyer', 'Iyer', 'ஐயர்', 'Tamil Brahmin community known for scholarship, ritual knowledge and a deep-rooted family culture.', 'கல்வியிலும் பண்பாட்டிலும் சிறந்து விளங்கும் தமிழ் பிராமண சமூகம்.', 3, true),
  ('iyengar', 'Iyengar', 'ஐயங்கார்', 'Vaishnava Brahmin community with a rich tradition of bhakti, discipline and strong family bonds.', 'பக்தி, ஒழுக்கம் மற்றும் குடும்பப் பாசத்தால் சிறந்த வைணவ பிராமண சமூகம்.', 2, true),
  ('reddy', 'Reddy', 'ரெட்டி', 'Agrarian community known for entrepreneurship, philanthropy and commanding respect across regions.', 'விவசாயத்திலும் வணிகத்திலும் சிறந்து விளங்கும் உள்ளூர் சமூகம்.', 1, true),
  ('pillai', 'Pillai', 'பிள்ளை', 'One of the most widespread Tamil communities — educated, industrious and deeply family-oriented.', 'கல்வி, உழைப்பு மற்றும் குடும்ப பாசத்தில் சிறந்த தமிழ் சமூகம்.', 2, true),
  ('chettiar', 'Chettiar', 'செட்டியார்', 'Celebrated merchant community of Tamil Nadu, historically famed for banking, trade and global enterprise.', 'வரலாற்றில் வணிகம், வங்கியியல் ஆகியவற்றில் புகழ் பெற்ற தமிழ் சமூகம்.', 2, true),
  ('mudaliar', 'Mudaliar', 'முதலியார்', 'Respected Tamil community with a legacy of leadership, agriculture and service to society.', 'தலைமைப் பண்பும் சமூக சேவையும் கொண்ட கெளரவமான தமிழ் சமூகம்.', 1, true),
  ('gounder', 'Gounder', 'கவுண்டர்', 'Predominantly Kongu region community — progressive, agrarian and known for strong family discipline.', 'கொங்கு பகுதியில் சிறந்து விளங்கும் முற்போக்கான, உழைப்பாளி சமூகம்.', 1, true),
  ('naidu', 'Naidu', 'நாயுடு', 'Ambitious community prominent in business and politics across coastal Andhra and Tamil Nadu.', 'வணிகம் மற்றும் அரசியலில் சிறந்து விளங்கும் முன்னேறிய சமூகம்.', 1, true),
  ('thevar', 'Thevar', 'தேவர்', 'Brave and fiercely traditional community of southern Tamil Nadu, known for unity and respect.', 'வீரமும் மரபும் கொண்ட தென் தமிழகத்தின் ஒற்றுமையான சமூகம்.', 1, true),
  ('pandian', 'Pandian', 'பாண்டியன்', 'Honoured for its link to the ancient Pandya dynasty — proud, cultured and family-centred.', 'பண்டைய பாண்டியர் மரபுடன் தொடர்புடைய பெருமைமிக்க சமூகம்.', 0, true),
  ('nadar', 'Nadar', 'நாடார்', 'Industrious community that developed through trade and business, today highly educated.', 'வணிகத்தால் வளர்ந்து இன்று கல்வியில் சிறந்து விளங்கும் சமூகம்.', 0, true),
  ('vanniyar', 'Vanniyar', 'வன்னியர்', 'Major agrarian community of northern Tamil Nadu, rooted in village life and family values.', 'வட தமிழகத்தின் முதன்மை விவசாய சமூகம், கிராமப் பண்பாட்டில் வேரூன்றியது.', 0, true),
  ('kumar', 'Kumar', 'குமார்', 'Warrior-origin community of Tamil Nadu known for loyalty, simplicity and strong family values.', 'வீரம், எளிமை மற்றும் குடும்ப மதிப்புகள் கொண்ட தமிழ் சமூகம்.', 0, true),
  ('raman', 'Raman', 'ராமன்', 'A respected Tamil community rooted in agriculture, education and traditional family values.', 'விவசாயம், கல்வி, பாரம்பரிய குடும்ப மதிப்புகளில் வேரூன்றிய சமூகம்.', 0, true),

  ('kongu-vellalar', 'Kongu Vellalar', 'கொங்கு வேளாளர்', 'Agricultural community of the Kongu Nadu region, known for hard work and close-knit families.', 'கொங்கு நாட்டின் உழைப்பாளி, நெருக்கமான குடும்ப பிணைப்பு கொண்ட சமூகம்.', 0, true)
on conflict (id) do update
   set name                = excluded.name,
       tamil_name          = excluded.tamil_name,
       description         = excluded.description,
       tamil_description   = excluded.tamil_description,
       visible_members     = excluded.visible_members,
       active              = excluded.active;

insert into public.profiles (id, profile_id, user_id, full_name, gender, date_of_birth, age, height, marital_status, religion, community, caste, mother_tongue, state, district, city, education, college, profession, company, income, country, about, father_occupation, mother_occupation, brother_count, sister_count, family_type, family_location, family_values, gotra, horoscope_required, diet, smoking, drinking, hobbies, fitness, sports, music, food, appearances, min_age, max_age, min_height, max_height, pref_religion, pref_mother_tongues, pref_communities, pref_education, pref_professions, pref_locations, pref_income, pref_diet, pref_smoking, pref_drinking, pref_marital_statuses, verified, status, online, last_active, profile_created_on, horoscope_link) values
  ('14fcfe14-721e-4739-80fb-53361dacfd16', 'p-praveen', 'user-praveen', 'Praveen Kumar', 'male', '1996-03-18', 30, 176, 'single', 'Hindu', 'Kumar', 'Kosar', 'Tamil', 'Tamil Nadu', 'Coimbatore', 'Coimbatore', 'B.E. Computer Science', 'Karpagam College of Engineering', 'Software Engineer', 'Thoughtworks', '₹25 - ₹50 Lakh', 'India', 'I''m a software engineer who keeps things simple — good coffee, long walks, and honest conversations. Raised in Coimbatore with strong family values, I''m looking for a partner who is kind, grounded, and excited to build a beautiful life together — someone who respects family and knows how to balance ambition with warmth.', 'Retired Government Officer', 'Home Maker', 1, 0, 'nuclear', 'Coimbatore, Tamil Nadu', 'Moderate, Cultured', 'Bharadwaj', false, 'vegetarian', 'never', 'never', '{"Reading","Classical music","Cricket","Trekking"}', 'Gym, 4 times a week', 'Cricket', 'Hindustani classical', 'Home-cooked meals, South Indian', 'Smart casual, traditional on festivals', 24, 32, 155, 172, 'Hindu', '{"Tamil","Hindi","English"}', '{"Any"}', '{"B.E / B.Tech","MBA","M.E / M.Tech"}', '{"Software Engineer","Product Manager","Chartered Accountant","Investment Analyst"}', '{"Coimbatore","Chennai","Chennai","Tiruchirappalli"}', '₹15 - ₹25 Lakh', 'vegetarian', 'never', 'never', '{"single"}', true, 'active', true, '2026-09-21T08:15:00.000Z', '2025-11-02', null),
  ('ad4373d6-802d-4942-8080-bc9824daeddc', 'p-ananya', 'user-ananya', 'Ananya Iyer', 'female', '2000-02-18', 26, 160, 'single', 'Hindu', 'Iyer', 'Iyer', 'Tamil', 'Tamil Nadu', 'Chennai', 'Chennai', 'MBA in Marketing', 'ICAI Institute', 'Product Manager', 'Flipkart', '₹25 - ₹50 Lakh', 'India', 'Product manager by profession, foodie by heart. Brought up in Chennai with a strong Tamil upbringing, I love Carnatic music and weekend trips to the coast. Looking for someone who is ambitious yet caring, and who treats family as their greatest strength.', 'Senior Auditor', 'Professor (Retd.)', 0, 1, 'nuclear', 'Chennai, Tamil Nadu', 'Traditional, Cultured', null, false, 'vegetarian', 'never', 'socially', '{"Carnatic music","Baking","Reading","Travel"}', 'Running', 'Badminton', 'Carnatic and jazz', 'South Indian, Italian', 'Prefers light western wear, occasional saree', 27, 33, 170, 188, 'Hindu', '{"Tamil"}', '{"Any"}', '{"B.E / B.Tech","MBA","M.E / M.Tech"}', '{"Software Engineer","Product Manager","Consultant"}', '{"Chennai","Coimbatore"}', '₹15 - ₹25 Lakh', 'vegetarian', 'never', 'never', '{"single"}', true, 'active', false, '2026-09-20T18:40:00.000Z', '2025-12-14', null),
  ('5f5a0b29-cf75-4fb6-83ff-6349fa2cde4c', 'p-meera', null, 'Meera Pillai', 'female', '1998-11-03', 27, 162, 'single', 'Hindu', 'Pillai', 'Pillai', 'Tamil', 'Tamil Nadu', 'Kumbakonam', 'Kumbakonam', 'B.Arch', 'SRM School of Architecture', 'Architect', 'Studio Murali', '₹15 - ₹25 Lakh', 'India', 'I design spaces that people call home — it''s a job I''m deeply passionate about. Calm, creative, and slightly introverted. I believe a marriage is built on friendship, patience, and shared dreams. Looking for a partner grounded in values who loves simple living and thoughtful conversation.', 'Port Engineer', 'Teacher', 1, 0, 'nuclear', 'Kumbakonam, Tamil Nadu', 'Liberal, Educated', null, false, 'eggetarian', 'never', 'socially', '{"Sketching","Photography","Gardening"}', 'Morning walks', 'Swimming', 'Graceful, ambient', 'Tamil cuisine, Italian', 'Minimal and elegant', 28, 35, 170, 190, 'Hindu', '{"Malayalam","English"}', '{"Any"}', '{"B.E / B.Tech","MBA","B.Arch"}', '{"Architect","Doctor","Consultant","Software Engineer"}', '{"Kumbakonam","Coimbatore","Tiruchirappalli"}', '₹15 - ₹25 Lakh', 'eggetarian', 'never', 'socially', '{"single"}', true, 'active', false, '2026-09-19T11:30:00.000Z', '2025-10-05', null),
  ('d6369a45-ef72-4ee1-80e4-47a4cf272544', 'p-riya', null, 'Ramya Chettiar', 'female', '1997-05-16', 29, 161, 'single', 'Hindu', 'Chettiar', 'Chettiar', 'Tamil', 'Tamil Nadu', 'Tiruchirappalli', 'Tiruchirappalli', 'CA', 'ICAI Institute of Chartered Accountants', 'Chartered Accountant', 'Deloitte', '₹25 - ₹50 Lakh', 'India', 'A disciplined CA with a soft heart. I love Navaratri kolam, Chettinad thali on Sundays, and reading philosophy. My family runs a small ancestral business. I value honesty over everything and am looking for a partner with strong ethics and a warm smile.', 'Business Owner', 'Home Maker', 0, 2, 'joint', 'Tiruchirappalli, Tamil Nadu', 'Traditional, Jain values', null, true, 'jain', 'never', 'never', '{"Kolam","Reading","Mandala art"}', 'Yoga', 'Golf (occasional)', 'Carnatic classical', 'Thalis, vegetarian food', 'Traditional wear lover', 29, 35, 172, 188, 'Jain', '{"Tamil"}', '{"Shwetambar","Digambar"}', '{"CA","MBA","B.E / B.Tech"}', '{"Chartered Accountant","Business Owner","Consultant"}', '{"Tiruchirappalli","Madurai"}', '₹15 - ₹25 Lakh', 'jain', 'never', 'never', '{"single"}', true, 'active', true, '2026-09-21T07:30:00.000Z', '2025-09-15', null),
  ('23aa9a34-2d22-4783-a791-b69bd79f6db4', 'p-arjun', 'user-arjun', 'Arjun Krishnan', 'male', '1994-08-15', 32, 178, 'single', 'Hindu', 'Iyengar', 'Iyengar', 'Tamil', 'Tamil Nadu', 'Chennai', 'Chennai', 'B.E. Mechanical', 'Anna University', 'Software Engineer', 'Zoho', '₹15 - ₹25 Lakh', 'India', 'Chennai-boy with a love for temple mornings and quiet weekends. I build automation tools during the day and read Tamil literature at night. Family says I am too fussy about food — I say I simply know good idli. Looking for someone warm, respectful and rooted in values.', 'Retired Bank Manager', 'Home Maker', 1, 1, 'nuclear', 'Chennai, Tamil Nadu', 'Traditional', 'Srinivasa', true, 'vegetarian', 'never', 'never', '{"Tamil literature","Cycling","Cooking","Temple visits"}', 'Jogging, 5 km daily', 'Badminton', 'Carnatic, ilaiyaraaja', 'South Indian, strictly veg', 'Classic and neat', 26, 34, 158, 180, 'Hindu', '{"Tamil"}', '{"Iyengar","Iyer"}', '{"B.E / B.Tech","MBA","CA","MBBS"}', '{"Software Engineer","Product Manager","Doctor","Consultant"}', '{"Chennai","Coimbatore"}', '₹10 - ₹15 Lakh', 'vegetarian', 'never', 'never', '{"single"}', true, 'active', true, '2026-09-21T09:10:00.000Z', '2026-01-18', null),
  ('d9ee01fc-314e-4959-b42a-c23747f1a146', 'p-karthik', 'user-karthik', 'Karthik Raman', 'male', '1993-12-02', 32, 176, 'single', 'Hindu', 'Chettiar', 'Chettiar', 'Tamil', 'Tamil Nadu', 'Madurai', 'Madurai', 'MBA Finance', 'Madras School of Economics', 'Business Owner', 'Raman Textiles', '₹25 - ₹50 Lakh', 'India', 'Third-generation textile merchant from Madurai. I run the family business with my father and uncle, and have started a small e-commerce arm for silk exports. Grounded, hardworking and big on festivals. Looking for a partner who values family and has her own ambitions too.', 'Business Owner', 'Home Maker', 0, 1, 'joint', 'Madurai, Tamil Nadu', 'Traditional, Commercial', 'Koundinya', true, 'vegetarian', 'never', 'never', '{"Business networking","Temple festivals","Cycling"}', 'Cricket on weekends', 'Cricket', 'Tamil classical', 'Chettinad thali', 'Formal traditional', 24, 30, 155, 175, 'Hindu', '{"Tamil"}', '{"Chettiar","Iyer","Iyengar"}', '{"MBA","CA","B.E / B.Tech"}', '{"Chartered Accountant","Business Owner","Product Manager"}', '{"Madurai","Chennai","Coimbatore"}', '₹15 - ₹25 Lakh', 'vegetarian', 'never', 'never', '{"single"}', true, 'active', false, '2026-09-20T14:20:00.000Z', '2026-02-09', null),
