  ('4239aab4-0b30-4308-bdf7-7ab3edcb255d', 'p-balaji', null, 'Balaji Subramanian', 'male', '1993-12-05', 32, 176, 'single', 'Hindu', 'Chettiar', 'Chettiar', 'Tamil', 'Tamil Nadu', 'Tiruchirappalli', 'Tiruchirappalli', 'MBA (Finance)', 'Madras School of Economics', 'Banker', 'Indian Bank', '₹25 - ₹50 Lakh', 'India', 'Branch manager in Trichy, amateur tabla player, and the person in my family who knows every family birthday. I like numbers, silence and long drives. Looking for a partner with a calm mind, a kind heart and the patience for a family that talks a lot.', 'Business Owner', 'Home Maker', 0, 2, 'joint', 'Tiruchirappalli, Tamil Nadu', 'Traditional, Commercial', 'Koundinya', true, 'vegetarian', 'never', 'occasionally', '{"Tabla","Reading","Cricket","Temple music"}', 'Walking and gym', 'Cricket', 'Carnatic and devotional', 'Vegetarian, temple style', 'Formal traditional', 26, 35, 158, 180, 'Hindu', '{"Tamil","Hindi"}', '{"Chettiar","Iyer","Iyengar","Mudaliar"}', '{"MBA","CA","M.Com"}', '{"Banker","Chartered Accountant","Business Owner","Civil Services"}', '{"Tiruchirappalli","Chennai","Madurai"}', '₹15 - ₹25 Lakh', 'vegetarian', 'never', 'occasionally', '{"single"}', true, 'active', false, '2026-09-19T18:05:00.000Z', '2025-11-15', null),
  ('2f2c51c0-3076-4838-8925-ac1c15e7582c', 'p-muthuvel', null, 'Muthuvel Natarajan', 'male', '1997-09-11', 29, 181, 'single', 'Hindu', 'Pillai', 'Pillai', 'Tamil', 'Tamil Nadu', 'Salem', 'Salem', 'MBBS', 'Stanley Medical College', 'Doctor', 'Government District Hospital', '₹15 - ₹25 Lakh', 'India', 'A government doctor in Salem: long shifts, shorter temper, and a soft spot for everyone who walks into my OPD. I cook a very decent rasam and I have never once missed a family function. Looking for a partner who is patient, understanding and ready for a life that starts early.', 'Doctor', 'Home Maker', 1, 0, 'nuclear', 'Salem, Tamil Nadu', 'Traditional, Devout', 'Bharadwaja', true, 'vegetarian', 'never', 'never', '{"Running","Reading","Temple visits","Teaching"}', 'Running, five kilometres daily', 'Football', 'Old Tamil film and Carnatic', 'Simple vegetarian, home cooked', 'Simple and neat', 27, 34, 158, 180, 'Hindu', '{"Tamil"}', '{"Pillai","Iyer","Mudaliar"}', '{"MBBS","MD / MS","BDS","B.Sc"}', '{"Doctor","Pharmacist","Teacher","Civil Services"}', '{"Salem","Coimbatore","Chennai","Erode"}', '₹15 - ₹25 Lakh', 'vegetarian', 'never', 'never', '{"single"}', true, 'active', true, '2026-09-21T07:15:00.000Z', '2026-04-21', null),
  ('901fa487-6b7d-431d-bde9-b5755a61c602', 'p-gokul', null, 'Gokulakrishnan Muthukumar', 'male', '1999-06-23', 27, 175, 'single', 'Hindu', 'Mudaliar', 'Mudaliar', 'Tamil', 'Tamil Nadu', 'Erode', 'Erode', 'LLB', 'Dr. Ambedkar Law College', 'Lawyer', 'District Court', '₹10 - ₹15 Lakh', 'India', 'I argue for a living and I apologise for it within a week. Courtroom lawyer, amateur biryani chef, and the eldest of three. Looking for someone who can hold her own opinion, laugh at mine and never let a fight go past bedtime.', 'Government Employee', 'Home Maker', 0, 2, 'nuclear', 'Erode, Tamil Nadu', 'Progressive, Educated', 'Bharadwaj', false, 'non-vegetarian', 'never', 'socially', '{"Debating","Biryani","Cricket","Motorcycling"}', 'Football, twice a week', 'Cricket', 'Ilaiyaraaja and Kishore Kumar', 'Biryani, non-vegetarian', 'Smart casual', 26, 33, 158, 180, 'Hindu', '{"Tamil","English"}', '{"Any"}', '{"LLB","BBA","B.Com","MBA"}', '{"Lawyer","Business Owner","Banker","Marketing Manager"}', '{"Erode","Coimbatore","Chennai"}', '₹10 - ₹15 Lakh', 'non-vegetarian', 'never', 'socially', '{"single"}', true, 'active', false, '2026-09-20T19:50:00.000Z', '2026-07-09', null),
  ('2f55abec-2b7e-4453-ade4-ae95a7bc869a', 'p-naveen', null, 'Naveen Chandran', 'male', '1994-02-28', 32, 179, 'single', 'Hindu', 'Reddy', 'Reddy', 'Telugu', 'Tamil Nadu', 'Chennai', 'Chennai', 'M.E / M.Tech (Data Science)', 'IIT Madras', 'Data Scientist', 'Amazon', '₹50 Lakh - ₹1 Crore', 'India', 'I build models that predict what people will buy and I still cannot predict what I will cook tonight. IIT background, Telugu at home, Tamil by choice. Looking for a partner who is intellectually curious, financially clear and warm in a way that does not need an audience.', 'Software Professional', 'Home Maker', 1, 0, 'nuclear', 'Chennai, Tamil Nadu', 'Progressive, Educated', 'Koundinya', false, 'non-vegetarian', 'never', 'socially', '{"Cycling","Sci-fi reading","Coffee","Photography"}', 'Cycling and swimming', 'Cricket', 'Telugu and English indie', 'Biryani and continental experiments', 'Smart casual', 27, 35, 158, 182, 'Hindu', '{"Telugu","Tamil","English"}', '{"Reddy","Naidu","Any"}', '{"M.E / M.Tech","Ph.D","B.E / B.Tech","MBA"}', '{"Data Scientist","Software Engineer","Product Manager","Doctor"}', '{"Chennai","Hyderabad","Bengaluru"}', '₹25 - ₹50 Lakh', 'non-vegetarian', 'never', 'socially', '{"single"}', true, 'active', true, '2026-09-21T08:40:00.000Z', '2025-12-22', null),
  ('168bdb43-54e3-4b64-83db-b7622d181062', 'p-surendar', null, 'Surendar Naidu', 'male', '1996-09-03', 30, 177, 'single', 'Hindu', 'Naidu', 'Naidu', 'Telugu', 'Tamil Nadu', 'Krishnagiri', 'Hosur', 'B.E / B.Tech (Mechanical)', 'PSG College of Technology', 'Marketing Manager', 'TVS Motor Company', '₹25 - ₹50 Lakh', 'India', 'I spend my weekdays reading dealer reports and my weekends at a cricket ground in Hosur. Telugu household, Tamil schooling, and a habit of finishing what I start. Looking for a partner who is warm, straightforward and happy to be part of a very involved family.', 'Farmer', 'Home Maker', 0, 1, 'joint', 'Krishnagiri, Tamil Nadu', 'Moderate, Close-knit', 'Kaundinya', false, 'vegetarian', 'never', 'socially', '{"Cricket","Trekking","Temple music","Cooking"}', 'Gym, four times a week', 'Cricket', 'Telugu and Carnatic', 'Telugu and Tamil home cooking', 'Smart casual, ethnic on festivals', 26, 34, 158, 180, 'Hindu', '{"Telugu","Kannada","Tamil"}', '{"Naidu","Reddy","Any"}', '{"B.E / B.Tech","MBA","M.E / M.Tech"}', '{"Marketing Manager","Business Owner","Mechanical Engineer","Banker"}', '{"Krishnagiri","Chennai","Coimbatore"}', '₹15 - ₹25 Lakh', 'vegetarian', 'never', 'socially', '{"single"}', true, 'active', false, '2026-09-19T10:30:00.000Z', '2026-02-24', null),
  ('8d42d6e0-c00d-4a27-8a89-eda57e4c1c20', 'p-kavin', null, 'Kavin Perumal', 'male', '1998-04-27', 28, 170, 'single', 'Hindu', 'Pandian', 'Pandian', 'Tamil', 'Tamil Nadu', 'Tirunelveli', 'Tirunelveli', 'BBA', 'Tirunelveli Manonmaniam Sundaranar University', 'Civil Services', 'Indian Revenue Service', '₹25 - ₹50 Lakh', 'India', 'District collector in the making, currently posted in Tirunelveli. I write files nobody reads and I volunteer at a reading club every Saturday, which should tell you what kind of person I am. Looking for a partner with patience, a sense of humour and her own ambitions.', 'Government Employee', 'Home Maker', 1, 0, 'nuclear', 'Tirunelveli, Tamil Nadu', 'Traditional, Cultured', 'Bharadwaja', true, 'vegetarian', 'never', 'socially', '{"Reading","Running","Temple festivals","Documentaries"}', 'Running, four mornings a week', 'Volleyball', 'Carnatic and Tamil devotional', 'Tamil food, home cooked', 'Neat and traditional', 27, 34, 158, 180, 'Hindu', '{"Tamil"}', '{"Pandian","Nadar","Pillai","Thevar"}', '{"BBA","B.Com","MBA","M.A"}', '{"Civil Services","Banker","Teacher","Chartered Accountant"}', '{"Tirunelveli","Madurai","Chennai","Coimbatore"}', '₹15 - ₹25 Lakh', 'vegetarian', 'never', 'socially', '{"single"}', true, 'active', true, '2026-09-21T06:05:00.000Z', '2026-05-30', null),
  ('2abf06ea-75bd-4e33-baf9-50e6bbfd779c', 'p-sridharan', null, 'Sridharan Rajagopalan', 'male', '1992-11-15', 33, 183, 'single', 'Hindu', 'Iyengar', 'Iyengar', 'Tamil', 'Tamil Nadu', 'Chennai', 'Chennai', 'Ph.D (Mathematics)', 'IIT Madras', 'Professor', 'IIT Madras', '₹50 Lakh - ₹1 Crore', 'India', 'I teach mathematics at IIT Madras and I still get nervous before a first-year lecture. Vegetarian, chess on Sundays, and a family that discusses literature at dinner. Looking for a partner who is thoughtful, well-read and comfortable with a household that talks for a living.', 'Retired Professor', 'Home Maker', 0, 1, 'nuclear', 'Chennai, Tamil Nadu', 'Progressive, Educated', 'Srinivasa', false, 'vegetarian', 'never', 'occasionally', '{"Chess","Classical music","Reading","Temple visits"}', 'Walking, four kilometres', 'Cricket', 'Carnatic and western classical', 'Vegetarian, temple and home', 'Smart and understated', 28, 37, 158, 186, 'Hindu', '{"Tamil","English"}', '{"Iyengar","Iyer","Chettiar"}', '{"Ph.D","M.E / M.Tech","B.E / B.Tech","MBA"}', '{"Professor","Doctor","Data Scientist","Product Manager"}', '{"Chennai","Coimbatore"}', '₹25 - ₹50 Lakh', 'vegetarian', 'never', 'occasionally', '{"single"}', true, 'active', false, '2026-09-18T17:45:00.000Z', '2025-10-28', null)
