-- temple_services --------------------------------------------------------------
-- price is whole rupees. 0 renders as "On request" rather than "₹0", so ask-the-
-- temple stays distinguishable from a genuinely free entry. every temple carries
-- ten packages, so the services panel is populated for all five.
--
-- tmpl-5 carries is_available = false on one row on purpose: it is the row the
-- admin dashboard needs in order to show a disabled package that the public
-- detail page must not render. is_featured is set on one service per temple so
-- the highlight treatment has something to pick up.
--
-- temple_services.image is a schema column nothing reads yet — the public
-- service card shows name, details and price only — so it is left out of this
-- insert rather than filled with nulls twenty-one times.
--
-- ids are readable and stable rather than generated, so re-running this seed
-- updates the rows instead of inserting duplicates.
insert into public.temple_services (id, temple_id, name, details, price, terms, is_available, is_featured, sort_order) values
  ('tsvc-1', 'tmpl-1', 'Kalyanam arrangements', 'Full wedding coordination across all temple rituals, from muhurtam booking to the kalyanam itself, including flower decoration, lamps and traditional attire.', 35000, 'Booked at least 30 days ahead. 50% non-refundable on confirmation.', true, true, 1),
  ('tsvc-2', 'tmpl-1', 'Kanyadaan ceremony', 'The tying of the thaali with priestly chanting, homam and blessings, including preparation of the rice, coconuts and turmeric items.', 7500, 'Includes one hour of exclusive time in the mandapam.', true, false, 2),
  ('tsvc-3', 'tmpl-1', 'Engagement and Oonjal', 'Engagement ceremony with blessings and a coordinated Oonjal evening with musicians and refreshments.', 18000, 'Oonjal slot held for four hours.', true, false, 3),
