  ('tsvc-6', 'tmpl-1', 'Photography inside the temple', 'Permission to photograph in the inner corridors and the mandapam, with a temple-approved photographer.', 0, 'Photographer fees are separate and quoted on request.', true, false, 6),

  ('tsvc-7', 'tmpl-2', 'Kalyanam arrangements', 'Complete wedding coordination inside the longest temple corridor in the world, with pooja arrangements, mandapam decoration and priests for the full sequence of rituals.', 40000, 'Booked at least 45 days ahead for the corridor. 50% non-refundable.', true, true, 1),
