  ('tsvc-9', 'tmpl-2', 'Darshan and puja booking', 'Priority darshan slots and private puja in the sanctum, booked through the temple office.', 3000, null, true, false, 3),
  ('tsvc-10', 'tmpl-2', 'Kanni Moolam astrology consultation', 'Traditional muhurtam matching with the temple astrologer for an auspicious wedding date.', 2000, null, true, false, 4),
  ('tsvc-11', 'tmpl-2', 'Temple wedding hall hire', 'Exclusive use of the wedding hall for the reception, with chairs, stage and lighting.', 25000, 'Six-hour slot including setup and cleanup.', true, false, 5),

  ('tsvc-12', 'tmpl-3', 'Kalyanam arrangements', 'Coastal temple wedding coordination with full ritual support, decoration and priest service, arranged with the temple administration.', 30000, 'Booked at least 30 days ahead. 50% non-refundable.', true, true, 1),
  ('tsvc-13', 'tmpl-3', 'Kanyadaan ceremony', 'Thaali tying and blessings by the temple priests, with homam and traditional offerings.', 7000, null, true, false, 2),
