  ('tsvc-18', 'tmpl-4', 'Musical pillar hall booking', 'Use of one of the seven musical pillar halls for the wedding ceremony or reception.', 18000, 'Hall availability depends on the pillar chosen, confirmed at booking.', true, false, 3),

